import { defineConfig } from "vite";
import {
  applicationPlugins,
  prerenderPlugin,
} from "@kasperrt/smolter/preact/vite";

export default defineConfig(({ isSsrBuild }) => ({
  plugins: [
    ...applicationPlugins(),
    prerenderPlugin({ paths: ["/", "/about"] }),
  ],
  build: {
    outDir: isSsrBuild ? "dist/server" : "dist/client",
    rollupOptions: {
      input: isSsrBuild
        ? "src/entry.server.tsx"
        : "src/entry.client.tsx",
    },
  },
}));

prerenderPlugin({
  paths: async (staticPaths) => {
    const publishedPaths = await readPublishedPaths();
    return [
      ...staticPaths.filter((path) => ["/", "/about"].includes(path)),
      ...publishedPaths,
    ];
  },
});
